function shortestCut(nums: number[], p: number): number {
  const n = nums.length;
  const rem = nums.reduce((a, x) => (a + x) % p, 0);
  if (rem === 0) return 0;
  let best = n;
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let j = i; j < n; j++) {
      s = (s + nums[j]) % p;
      if (s === rem) { best = Math.min(best, j - i + 1); break; }
    }
  }
  return best === n ? -1 : best;
}

