function shortestCut(nums: number[], p: number): number {
  const n = nums.length;
  const rem = nums.reduce((a, x) => (a + x) % p, 0);
  if (rem === 0) return 0;
  const last = new Map<number, number>([[0, -1]]);
  let cur = 0, best = n;
  for (let j = 0; j < n; j++) {
    cur = (cur + nums[j]) % p;
    const i = last.get((cur - rem + p) % p);
    if (i !== undefined) best = Math.min(best, j - i);
    last.set(cur, j);
  }
  return best === n ? -1 : best;
}

